mapper.select:
SELECT fd.*
FROM flash_design fd

    JOIN flash_design_style fds ON fd.id = fds.flash_design_id

WHERE fd.is_active = true

    AND fd.artist_id = #{artistId}


    AND fds.style_id = #{styleId}

mapper.update:
UPDATE flash_design
SET artist_id = #{artistId},
title = #{title},
description = #{description},
image_url = #{imageUrl}
WHERE id = #{id}

UPDATE flash_design
SET is_active = FALSE
WHERE id = #{id}

UPDATE flash_design
SET is_active = FALSE
WHERE artist_id = #{artistId}

mapper.select:
SELECT s.* FROM style s
JOIN flash_design_style fds ON s.id = fds.style_id
WHERE fds.flash_design_id = #{flashDesignId}
